<form id="bulk-form" action="{{ route('admin.inventory.bulk') }}" method="POST" class="mt-4 flex flex-wrap items-center gap-3 border border-white/10 bg-black p-4">@csrf<span class="text-xs font-bold uppercase tracking-wider text-on-surface-variant">Bulk actions</span><label class="sr-only" for="bulk-action">Bulk action</label><select id="bulk-action" name="action" required class="rounded border-white/15 bg-surface px-3 py-2 text-sm text-white"><option value="">Choose action</option><option value="activate">Set active</option><option value="draft">Set draft</option><option value="scheduled">Set scheduled</option><option value="archive">Archive</option><option value="delete">Delete</option></select><button type="submit" class="bg-primary px-5 py-2 font-bold text-black hover:bg-lime-300">Save changes</button><span id="bulk-count" class="text-xs text-on-surface-variant">0 selected</span></form>
<script>
    (function () {
        const form = document.getElementById('bulk-form');
        const rows = document.querySelectorAll('tbody tr');
        const count = document.getElementById('bulk-count');
        rows.forEach(function (row) {
            const link = row.querySelector('a[href*="/products/"]');
            if (!link) return;
            const slug = link.getAttribute('href').split('/products/')[1].split(/[?#]/)[0];
            const cell = document.createElement('td');
            cell.className = 'px-4 py-4';
            cell.innerHTML = '<input type="checkbox" name="slugs[]" value="' + slug + '" form="bulk-form" class="product-check rounded border-white/20 bg-surface text-primary focus:ring-primary"><label class="sr-only">Select product</label>';
            row.prepend(cell);
        });
        const head = document.querySelector('thead tr');
        if (head) {
            const cell = document.createElement('th');
            cell.className = 'px-4 py-4';
            cell.innerHTML = '<input id="select-all" type="checkbox" form="bulk-form" class="rounded border-white/20 bg-surface text-primary focus:ring-primary"><label class="sr-only" for="select-all">Select all products</label>';
            head.prepend(cell);
        }
        const updateCount = function () {
            count.textContent = document.querySelectorAll('.product-check:checked').length + ' selected';
        };
        document.querySelectorAll('.product-check').forEach(function (checkbox) { checkbox.addEventListener('change', updateCount); });
        const selectAll = document.getElementById('select-all');
        if (selectAll) selectAll.addEventListener('change', function () {
            document.querySelectorAll('.product-check').forEach(function (checkbox) { checkbox.checked = selectAll.checked; });
            updateCount();
        });
        form.addEventListener('submit', function (event) {
            if (!document.querySelector('.product-check:checked')) { event.preventDefault(); alert('Select at least one product first.'); }
        });
    }());
</script>
