<script>
(() => {
    const variationSection = [...document.querySelectorAll('section')].find(section => section.querySelector('h2')?.textContent.trim() === 'Variation stock');
    if (variationSection) variationSection.hidden = true;
    document.querySelectorAll('tbody form[action*="/stock"]').forEach(rowForm => {
        const source = [...document.querySelectorAll('form[action*="/stock"]')].find(form => form !== rowForm && form.action === rowForm.action && form.querySelector('input[name^="stock_by_size"]'));
        if (!source) return;
        const cell = rowForm.closest('td');
        const details = document.createElement('details');
        details.className = 'relative';
        const summary = document.createElement('summary');
        summary.className = 'cursor-pointer list-none text-xs font-bold text-primary hover:text-white';
        summary.textContent = `${rowForm.closest('tr')?.querySelector('td:first-child p.font-semibold')?.textContent || 'Stock'} · edit sizes`;
        const form = document.createElement('form');
        form.method = 'POST';
        form.action = rowForm.action;
        form.className = 'absolute left-0 z-30 mt-2 grid w-64 grid-cols-4 gap-2 border border-white/20 bg-surface p-3 shadow-xl';
        const token = source.querySelector('input[name="_token"]');
        if (token) form.append(token.cloneNode(true));
        source.querySelectorAll('input[name^="stock_by_size"]').forEach(input => {
            const label = document.createElement('label');
            label.className = 'text-[9px] font-bold uppercase tracking-wider text-on-surface-variant';
            label.textContent = input.name.match(/\[([^\]]+)\]/)?.[1] || 'Size';
            const clone = input.cloneNode(true);
            clone.className = 'mt-1 w-full rounded border-white/15 bg-black px-2 py-1 text-white';
            label.append(clone);
            form.append(label);
        });
        const save = document.createElement('button');
        save.type = 'submit';
        save.className = 'col-span-4 bg-primary px-3 py-2 text-xs font-bold uppercase text-black';
        save.textContent = 'Save sizes';
        form.append(save);
        details.append(summary, form);
        rowForm.hidden = true;
        source.hidden = true;
        cell.prepend(details);
    });
})();
</script>
<script>
(() => {
    const closeDetails = except => document.querySelectorAll('details[open]').forEach(detail => {
        if (detail !== except) detail.removeAttribute('open');
    });
    document.addEventListener('toggle', event => {
        if (event.target instanceof HTMLDetailsElement && event.target.open) closeDetails(event.target);
    }, true);
    document.addEventListener('click', event => {
        if (!event.target.closest('details')) closeDetails(null);
    });
})();
</script>
<script>
document.querySelectorAll('a[href*="/products/"]').forEach(link => {
    link.target = '_blank';
    link.rel = 'noopener';
});
</script>
